-- キャラ(種族)の表示名・説明文をD1に移す(ユーザー指示、2026-08-29)。
-- これまでpublic/locales/*.jsの静的game.species.<id>.name/.descキーが唯一の情報源だったため、
-- 管理画面からキャラを追加してもコード追記＋デプロイをしないと名前が表示できなかった。
-- 既存61種×6言語ぶんは、当時のロケールファイルの内容からこのファイル生成時点でバックフィルする
-- (以後はこのテーブルが正。静的ロケールファイル側のgame.species.*キー自体は削除しない———
-- index.htmlのCOLLECTセクションが4種だけ固定サンプルとして直接参照しているため、
-- 残りの57種ぶんも含めて「使われなくなるが実害はない」データとして残置する)。

CREATE TABLE species_i18n (
  species_id TEXT NOT NULL REFERENCES species(id) ON DELETE CASCADE,
  lang       TEXT NOT NULL,
  name       TEXT NOT NULL,
  desc       TEXT,
  PRIMARY KEY (species_id, lang)
) STRICT;

